    sell_book = []  # list of (price, arrival_time, id, qty) tuples, sorted by priority
    trades = []
    arrival_time_counter = 0
    order_id_to_info = {}  # maps id to (side, arrival_time) for tracking state

    for order in orders:
        arrival_time_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_id_to_info:
                side, arrival_time = order_id_to_info[order_id]
                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]
                del order_id_to_info[order_id]

